from core.base.change.event_pattern import EventPattern
from core.base.command.handler import Handler
from core.base.guard.guard import Guard
from core.base.listener.commit_listener import CommitListener
from core.base.listener.deletion_listener import DeletionListener
from core.base.listener.save_listener import SaveListener
from core.base.model.model import Model
from core.base.model.tables import Tables
from core.base.module.dotted_path import DottedPath
from core.base.module.module import Module
from core.base.module.module_error import ModuleError

BUILT_IN_CHANGES = ("create", "update", "delete", "metadata")
LISTENER_BASES = (DeletionListener, SaveListener, CommitListener)


class ModuleCheck:
    """Checks the modules before a sync writes anything: every event a guard or listener names exists, no two
    modules claim one name, table or command, and every lifecycle is complete; all problems are reported at once."""

    def __init__(self, tables: Tables) -> None:
        self.tables = tables

    def known_events(self, modules: tuple[type[Module], ...]) -> tuple[str, ...]:
        events: list[str] = []
        for model in self.models(modules):
            moves = tuple(move.name for move in model.lifecycle.moves()) if model.lifecycle else ()
            events.extend(f"{model.name}.{change}" for change in BUILT_IN_CHANGES + moves)
        return tuple(events)

    def check(self, modules: tuple[type[Module], ...]) -> None:
        problems = self.name_clashes(modules) + self.lifecycle_problems(modules) + self.event_problems(modules) + self.handler_clashes(modules)
        if problems:
            raise ModuleError("the modules cannot be synced: " + "; ".join(problems))

    def models(self, modules: tuple[type[Module], ...]) -> tuple[type[Model], ...]:
        return tuple(noun.model for module in modules for noun in module.nouns)

    def name_clashes(self, modules: tuple[type[Module], ...]) -> tuple[str, ...]:
        models = self.models(modules)
        names = [model.name for model in models]
        tables = [self.tables.table(model).name for model in models]
        guards = [self.guard(path).name for module in modules for path in module.guards]
        listeners = [self.listener_name(path) for module in modules for path in module.listeners]
        return tuple(f"two {kind} named {name}" for kind, values in (("models", names), ("tables", tables), ("guards", guards), ("listeners", listeners))
                     for name in sorted({value for value in values if values.count(value) > 1}))

    def lifecycle_problems(self, modules: tuple[type[Module], ...]) -> tuple[str, ...]:
        problems: list[str] = []
        for model in self.models(modules):
            lifecycle = model.lifecycle
            if lifecycle is None:
                continue
            moves = lifecycle.moves()
            problems.extend(f"{model.__name__}'s move {move.name} is named like a built-in change" for move in moves if move.name in BUILT_IN_CHANGES)
            problems.extend(f"{model.__name__}'s move {name} is named unlike its attribute" for name in lifecycle.misnamed_moves())
            reachable = {move.target for move in moves} | set(lifecycle.initial)
            problems.extend(f"{model.__name__}'s state {state.value} is no move's target and not a first state" for state in lifecycle.states if state not in reachable)
        return tuple(problems)

    def event_problems(self, modules: tuple[type[Module], ...]) -> tuple[str, ...]:
        events = self.known_events(modules)
        named = [(self.guard(path).name, self.guard(path).event) for module in modules for path in module.guards]
        named += [(self.listener_name(path), self.listener_event(path)) for module in modules for path in module.listeners]
        return tuple(f"{name} covers {event}, which no model raises" for name, event in named if not any(EventPattern(event).matches(known) for known in events))

    def handler_clashes(self, modules: tuple[type[Module], ...]) -> tuple[str, ...]:
        commands = [DottedPath.class_path(self.handler(path).command).text for module in modules for path in module.handlers]
        return tuple(f"two handlers carry out {command}" for command in sorted({command for command in commands if commands.count(command) > 1}))

    def guard(self, path: str) -> type[Guard]:
        loaded = DottedPath(path).loaded()
        if not issubclass(loaded, Guard):
            raise ModuleError(f"{path} is no guard")
        return loaded

    def handler(self, path: str) -> type[Handler[object, object]]:
        loaded = DottedPath(path).loaded()
        if not issubclass(loaded, Handler):
            raise ModuleError(f"{path} is no handler")
        return loaded

    def listener_name(self, path: str) -> str:
        return self.listener(path).name

    def listener_event(self, path: str) -> str:
        return self.listener(path).event

    def listener(self, path: str) -> type[DeletionListener] | type[SaveListener] | type[CommitListener]:
        loaded = DottedPath(path).loaded()
        if issubclass(loaded, DeletionListener):
            return loaded
        if issubclass(loaded, SaveListener):
            return loaded
        if issubclass(loaded, CommitListener):
            return loaded
        raise ModuleError(f"{path} is no listener")

from dataclasses import dataclass

import pytest

from core.base.change.change import Change
from core.base.command.handlers.make_handler import MakeHandler
from core.base.guard.guard import Guard
from core.base.model.lifecycle import Lifecycle
from core.base.model.model import Model
from core.base.model.move import Move
from core.base.model.tables import Tables
from core.base.module.dotted_path import DottedPath
from core.base.module.module import Module
from core.base.module.module_check import ModuleCheck
from core.base.module.module_error import ModuleError
from core.base.module.noun import Noun
from tests.core.base.test_lifecycle import LoanLifecycle, LoanState
from tests.core.base.test_model import Loan


class LateLoansOnly(Guard):
    name = "loans.late-only"
    event = "loan.overdue"

    def check(self, change: Change[Model]) -> None:
        return None


class RenewedLoansOnly(Guard):
    name = "loans.renewed-only"
    event = "loan.renew"

    def check(self, change: Change[Model]) -> None:
        return None


class UpdateMoveLifecycle(Lifecycle):
    states = LoanState
    initial = (LoanState.LENT,)
    editable = ()
    deletable = ()

    update = Move("update", (LoanState.LENT,), LoanState.LATE)


class UnreachedStateLifecycle(Lifecycle):
    states = LoanState
    initial = (LoanState.LENT,)
    editable = ()
    deletable = ()

    overdue = Move("overdue", (LoanState.LENT,), LoanState.LATE)


class NoFirstStateLifecycle(Lifecycle):
    states = LoanState
    initial = ()
    editable = ()
    deletable = ()

    overdue = Move("overdue", (LoanState.LENT,), LoanState.LATE)


def model(lifecycle: type[Lifecycle], name: str = "book") -> type[Model]:
    return dataclass(frozen=True, kw_only=True)(type("Book", (Model,), {"name": name, "cli_noun": name, "lifecycle": lifecycle,
                                                                        "__annotations__": {"state": LoanState}, "state": LoanState.LENT}))


def module(name: str, nouns: tuple[Noun, ...] = (), guards: tuple[type, ...] = (), handlers: tuple[type, ...] = ()) -> type[Module]:
    paths = {"guards": tuple(DottedPath.class_path(guard).text for guard in guards), "handlers": tuple(DottedPath.class_path(handler).text for handler in handlers)}
    return type(name.title() + "Module", (Module,), {"name": name, "requires_core": ">=5", "nouns": nouns, **paths})


def problems(*modules: type[Module]) -> str:
    with pytest.raises(ModuleError) as caught:
        ModuleCheck(Tables()).check(modules)
    return str(caught.value)


def test_every_event_of_every_model_is_known():
    events = ModuleCheck(Tables()).known_events((module("loans", (Noun(Loan),)),))
    assert events == ("loan.create", "loan.update", "loan.delete", "loan.metadata", "loan.overdue", "loan.bring_back")


def test_modules_without_problems_pass():
    ModuleCheck(Tables()).check((module("loans", (Noun(Loan),), (LateLoansOnly,)),))


def test_a_guard_on_an_event_no_model_raises_is_refused():
    assert "loans.renewed-only covers loan.renew, which no model raises" in problems(module("loans", (Noun(Loan),), (RenewedLoansOnly,)))


def test_two_modules_with_one_model_name_and_table_are_refused():
    found = problems(module("loans", (Noun(Loan),)), module("library", (Noun(Loan),)))
    assert "two models named loan" in found and "two tables named loans" in found


def test_two_guards_with_one_name_are_refused():
