import hashlib

from core.base.module.dotted_path import DottedPath
from core.base.module.module import Module
from core.base.version import CORE_VERSION


class CodeFingerprint:
    """A hash of the core version and of every file the modules name, by path, size and change time, so a run
    can tell without importing anything that the registry was built from other code."""

    def text(self, modules: tuple[type[Module], ...]) -> str:
        digest = hashlib.sha256(".".join(map(str, CORE_VERSION)).encode())
        for path in sorted({file for module in modules for file in self.module_files(module)}):
            status = DottedPath(path).source_file().stat()
            digest.update(f"{DottedPath(path).source_file()}:{status.st_size}:{status.st_mtime_ns}".encode())
        return digest.hexdigest()

    def module_files(self, module: type[Module]) -> tuple[str, ...]:
        named = (*module.migrations, *module.views, *module.handlers, *module.subcommands, *module.guards, *module.listeners)
        nouns = tuple(DottedPath.class_path(noun.model).text for noun in module.nouns)
        return (DottedPath.class_path(module).text, *nouns, *named)

import json
import sys
from typing import TextIO

from core.base.guard_refusal import GuardRefusal
from core.base.metadata import Metadata
from core.base.model.model import Model
from core.base.model.table import stored
from core.base.model.tables import Tables
from core.base.query.page import Page
from core.base.refusal import Refusal

LIST_HIDDEN_COLUMNS = ("version", "metadata", "created_at", "updated_at", "created_by", "environment_id")


class Output:
    """Prints what a command gives back: plain lines for a person, or one JSON value with --json."""

    def __init__(self, tables: Tables, json_output: bool, stream: TextIO = sys.stdout) -> None:
        self.tables, self.json_output, self.stream = tables, json_output, stream

    def line(self, text: str) -> None:
        self.write(text, {"line": text})

    def row(self, model: Model) -> None:
        values = self.values(model)
        self.write("\n".join(f"{column}: {value}" for column, value in values.items() if value not in (None, {}, "")), values)

    def page(self, page: Page[Model]) -> None:
        lines = ["  ".join(str(value) for column, value in self.values(model).items() if column not in LIST_HIDDEN_COLUMNS) for model in page.rows]
        if not page.is_last:
            lines.append(f"page {page.number}, {len(page.rows)} of {page.total} rows: --page {page.number + 1} for the next")
        listing = {"rows": [self.values(model) for model in page.rows], "page": page.number, "size": page.size, "total": page.total}
        self.write("\n".join(lines) if lines else "nothing found", listing)

    def refusal(self, refusal: Refusal) -> None:
        guard, skip_flag = (refusal.guard, refusal.skip_flag) if isinstance(refusal, GuardRefusal) else ("", "")
        self.write(refusal.text, {"refused": refusal.reason, "suggestion": refusal.suggestion, "guard": guard, "skip_flag": skip_flag})

    def error(self, text: str) -> None:
        self.write(text, {"error": text})

    def values(self, model: Model) -> dict[str, object]:
        table = self.tables.table(type(model))
        return {column: self.json_value(getattr(model, column)) for column in table.columns}

    def json_value(self, value: object) -> object:
        if isinstance(value, Metadata):
            return json.loads(value.text)
        return stored(value)

    def write(self, text: str, data: object) -> None:
        self.stream.write((json.dumps(data, sort_keys=True) if self.json_output else text) + "\n")

from argparse import ArgumentParser, Namespace
from dataclasses import MISSING, Field, field, fields, make_dataclass
from enum import StrEnum
from types import new_class
from typing import Any, get_type_hints

from core.base.cli.caller import Caller
from core.base.cli.subcommand import Subcommand
from core.base.command.make_command import MakeCommand
from core.base.model.model import Model
from core.base.model.table import Table
from core.base.model.tables import Tables
from core.base.moment import Moment


class MakeSubcommand(Subcommand[MakeCommand[Model], Model]):
    """The `make` subcommand the core builds for a noun: the model's required fields as arguments, its optional
    fields as flags, run as a make command of that model."""

    name = "make"

    def __init__(self, table: Table) -> None:
        self.table = table
        self.cli_noun = table.model.cli_noun
        self.command_class = make_command_class(table)

    def arguments(self, parser: ArgumentParser) -> None:
        for column in self.table.required_fields:
            parser.add_argument(column, **argument_options(self.table.types[column]))
        for column in self.table.optional_fields:
            parser.add_argument(f"--{column.replace('_', '-')}", dest=column, **argument_options(self.table.types[column]))

    def command(self, arguments: Namespace, caller: Caller) -> MakeCommand[Model]:
        columns = (*self.table.required_fields, *self.table.optional_fields)
        given = {column: getattr(arguments, column) for column in columns if getattr(arguments, column) is not None}
        return self.command_class(**given)


class DefaultSubcommands:
    """Builds the subcommands every noun gets from its model, so a module writes only the ones that differ."""

    def __init__(self, tables: Tables) -> None:
        self.tables = tables

    def make(self, model: type[Model]) -> MakeSubcommand:
        return MakeSubcommand(self.tables.table(model))


def make_command_class(table: Table) -> type[MakeCommand[Model]]:
    hints = get_type_hints(table.model)
    model_fields = {model_field.name: model_field for model_field in fields(table.model)}
    command_fields = [(column, hints[column]) for column in table.required_fields]
    command_fields += [(column, hints[column], copied_default(model_fields[column])) for column in table.optional_fields]
    base = new_class(f"{table.model.__name__}MakeBase", (MakeCommand[table.model],))
    return make_dataclass(f"{table.model.__name__}Make", command_fields, bases=(base,), frozen=True)


def copied_default(model_field: Field[Any]) -> Field[Any]:
    if model_field.default is not MISSING:
        return field(default=model_field.default)
    return field(default_factory=model_field.default_factory)


def argument_options(kind: type) -> dict[str, Any]:
    if kind is bool:
        return {"action": "store_true", "default": None}
    if issubclass(kind, StrEnum):
        return {"type": kind, "choices": list(kind)}
    if kind is Moment:
        return {"type": Moment.parsed}
    return {"type": kind}

